CREATE OR REPLACE FUNCTION pg_temp.employee_owned_object(class_id oid, object_id oid) RETURNS boolean LANGUAGE sql STABLE SET search_path=pg_catalog,pg_temp AS $$
 SELECT coalesce(CASE class_id
 WHEN 'pg_class'::regclass THEN EXISTS(SELECT 1 FROM pg_class c WHERE c.oid=object_id AND (c.oid=ANY(ARRAY(SELECT to_regclass(x) FROM unnest(pg_temp.employee_tables())x)) OR c.oid IN(SELECT indexrelid FROM pg_index WHERE indrelid=ANY(ARRAY(SELECT to_regclass(x) FROM unnest(pg_temp.employee_tables())x)))))
 WHEN 'pg_proc'::regclass THEN object_id=ANY(ARRAY(SELECT to_regprocedure(x) FROM unnest(pg_temp.employee_entrypoints()||pg_temp.employee_helpers())x))
 WHEN 'pg_type'::regclass THEN EXISTS(SELECT 1 FROM pg_type t WHERE t.oid=object_id AND (t.typrelid=ANY(ARRAY(SELECT to_regclass(x) FROM unnest(pg_temp.employee_tables())x)) OR t.typelem IN(SELECT c.reltype FROM pg_class c WHERE c.oid=ANY(ARRAY(SELECT to_regclass(x) FROM unnest(pg_temp.employee_tables())x)))))
 WHEN 'pg_constraint'::regclass THEN EXISTS(SELECT 1 FROM pg_constraint c WHERE c.oid=object_id AND c.conrelid=ANY(ARRAY(SELECT to_regclass(x) FROM unnest(pg_temp.employee_tables())x)))
 WHEN 'pg_trigger'::regclass THEN EXISTS(SELECT 1 FROM pg_trigger t JOIN pg_constraint c ON c.oid=t.tgconstraint WHERE t.oid=object_id AND c.conrelid=ANY(ARRAY(SELECT to_regclass(x) FROM unnest(pg_temp.employee_tables())x)))
 WHEN 'pg_attrdef'::regclass THEN EXISTS(SELECT 1 FROM pg_attrdef d WHERE d.oid=object_id AND d.adrelid=ANY(ARRAY(SELECT to_regclass(x) FROM unnest(pg_temp.employee_tables())x)))
 ELSE false END,false)
$$;
CREATE OR REPLACE FUNCTION pg_temp.employee_acl(a aclitem[]) RETURNS jsonb LANGUAGE sql STABLE SET search_path=pg_catalog,pg_temp AS $$
 SELECT CASE WHEN a IS NULL THEN 'null'::jsonb ELSE coalesce((SELECT jsonb_agg(jsonb_build_array(pg_get_userbyid(grantor),CASE WHEN grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(grantee) END,privilege_type,is_grantable) ORDER BY grantor,grantee,privilege_type,is_grantable) FROM aclexplode(a)),'[]'::jsonb) END
$$;
-- Catalog-only semantic comparison. No credentials or user row contents.
-- Call after topology.sql inside the reviewed transaction; helpers are temporary.
CREATE OR REPLACE FUNCTION pg_temp.employee_catalog(hr boolean) RETURNS jsonb LANGUAGE sql STABLE SET search_path=pg_catalog,pg_temp AS $catalog$
WITH relations AS (
 SELECT c.*,n.nspname,format('%I.%I',n.nspname,c.relname) identity FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
 WHERE n.nspname IN('public','private','auth','storage') AND c.relkind IN('r','p','v','m','S','f','i','I')
 AND pg_temp.employee_owned_object('pg_class'::regclass,c.oid)=hr
), funcs AS (
 SELECT p.*,n.nspname FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
 WHERE n.nspname IN('public','private','auth','storage') AND p.prokind IN('f','p') AND pg_temp.employee_owned_object('pg_proc'::regclass,p.oid)=hr
), bodies AS (
 SELECT jsonb_build_object(
 'functions',coalesce((SELECT jsonb_object_agg(p.oid::regprocedure::text,jsonb_build_object('definition',pg_get_functiondef(p.oid),'owner',pg_get_userbyid(p.proowner),'acl',pg_temp.employee_acl(p.proacl),'kind',p.prokind,'securityDefiner',p.prosecdef,'volatility',p.provolatile,'leakproof',p.proleakproof,'strict',p.proisstrict,'parallel',p.proparallel,'config',p.proconfig,'result',pg_get_function_result(p.oid),'arguments',pg_get_function_arguments(p.oid)) ORDER BY p.oid::regprocedure::text) FROM funcs p),'{}'),
 'relations',coalesce((SELECT jsonb_object_agg(c.identity,jsonb_build_object('kind',c.relkind,'owner',pg_get_userbyid(c.relowner),'acl',pg_temp.employee_acl(c.relacl),'rls',c.relrowsecurity,'forceRls',c.relforcerowsecurity,'options',c.reloptions,'persistence',c.relpersistence,
 'columns',coalesce((SELECT jsonb_agg(jsonb_build_object('name',a.attname,'number',a.attnum,'type',format_type(a.atttypid,a.atttypmod),'nullable',NOT a.attnotnull,'identity',a.attidentity,'generated',a.attgenerated,'collation',CASE WHEN a.attcollation=0 THEN NULL ELSE a.attcollation::regcollation::text END,'default',pg_get_expr(d.adbin,d.adrelid),'acl',pg_temp.employee_acl(a.attacl)) ORDER BY a.attnum) FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped),'[]'),
 'constraints',coalesce((SELECT jsonb_agg(jsonb_build_object('name',x.conname,'definition',pg_get_constraintdef(x.oid,true),'validated',x.convalidated,'deferrable',x.condeferrable,'deferred',x.condeferred) ORDER BY x.conname) FROM pg_constraint x WHERE x.conrelid=c.oid),'[]'),
 'indexes',coalesce((SELECT jsonb_agg(jsonb_build_object('definition',pg_get_indexdef(i.indexrelid),'valid',i.indisvalid,'ready',i.indisready,'clustered',i.indisclustered,'replica',i.indisreplident) ORDER BY pg_get_indexdef(i.indexrelid)) FROM pg_index i WHERE i.indrelid=c.oid),'[]'),
 'policies',coalesce((SELECT jsonb_agg(jsonb_build_object('name',p.polname,'command',p.polcmd,'permissive',p.polpermissive,'roles',ARRAY(SELECT CASE WHEN r=0 THEN 'PUBLIC' ELSE pg_get_userbyid(r) END FROM unnest(p.polroles)r ORDER BY 1),'using',pg_get_expr(p.polqual,p.polrelid),'check',pg_get_expr(p.polwithcheck,p.polrelid)) ORDER BY p.polname) FROM pg_policy p WHERE p.polrelid=c.oid),'[]'),
 'triggers',coalesce((SELECT jsonb_agg(jsonb_build_object('name',CASE WHEN t.tgisinternal THEN (SELECT conname FROM pg_constraint WHERE oid=t.tgconstraint)||':'||t.tgtype::text ELSE t.tgname END,'function',t.tgfoid::regprocedure::text,'definition',CASE WHEN t.tgisinternal THEN replace(pg_get_triggerdef(t.oid,true),quote_ident(t.tgname),'<internal>') ELSE pg_get_triggerdef(t.oid,true) END,'enabled',t.tgenabled,'internal',t.tgisinternal) ORDER BY t.tgtype,t.tgfoid::regprocedure::text,CASE WHEN t.tgisinternal THEN (SELECT conname FROM pg_constraint WHERE oid=t.tgconstraint) ELSE t.tgname END) FROM pg_trigger t WHERE t.tgrelid=c.oid AND (hr OR NOT pg_temp.employee_owned_object('pg_trigger'::regclass,t.oid))),'[]'),
 'rules',coalesce((SELECT jsonb_agg(jsonb_build_object('name',r.rulename,'definition',pg_get_ruledef(r.oid,true),'enabled',r.ev_enabled) ORDER BY r.rulename) FROM pg_rewrite r WHERE r.ev_class=c.oid),'[]'),
 'view',CASE WHEN c.relkind IN('v','m') THEN pg_get_viewdef(c.oid,true) END,
 'sequence',(SELECT jsonb_build_object('type',s.seqtypid::regtype::text,'start',s.seqstart,'increment',s.seqincrement,'max',s.seqmax,'min',s.seqmin,'cache',s.seqcache,'cycle',s.seqcycle) FROM pg_sequence s WHERE s.seqrelid=c.oid)) ORDER BY c.identity) FROM relations c),'{}'),
 'types',coalesce((SELECT jsonb_object_agg(format('%I.%I',n.nspname,t.typname),jsonb_build_object('kind',t.typtype,'owner',pg_get_userbyid(t.typowner),'acl',pg_temp.employee_acl(t.typacl),'notnull',t.typnotnull,'default',t.typdefault,'base',CASE WHEN t.typbasetype=0 THEN NULL ELSE t.typbasetype::regtype::text END,'enum',ARRAY(SELECT e.enumlabel FROM pg_enum e WHERE e.enumtypid=t.oid ORDER BY e.enumsortorder)) ORDER BY n.nspname,t.typname) FROM pg_type t JOIN pg_namespace n ON n.oid=t.typnamespace WHERE n.nspname IN('public','private','auth','storage') AND pg_temp.employee_owned_object('pg_type'::regclass,t.oid)=hr),'{}'),
 'dependencies',coalesce((SELECT jsonb_agg(jsonb_build_array(a.type,a.schema,a.identity,d.objsubid,b.type,b.schema,b.identity,d.refobjsubid,d.deptype) ORDER BY a.type,a.schema,a.identity,d.objsubid,b.type,b.schema,b.identity,d.refobjsubid,d.deptype)
 FROM pg_depend d CROSS JOIN LATERAL pg_identify_object(d.classid,d.objid,d.objsubid)a CROSS JOIN LATERAL pg_identify_object(d.refclassid,d.refobjid,d.refobjsubid)b
 WHERE a.schema IN('public','private','auth','storage') AND pg_temp.employee_owned_object(d.classid,d.objid)=hr
 AND NOT (d.classid='pg_trigger'::regclass AND EXISTS(SELECT 1 FROM pg_trigger t WHERE t.oid=d.objid AND t.tgisinternal))
 AND (hr OR NOT pg_temp.employee_owned_object(d.refclassid,d.refobjid))),'[]')
 ) value
)
SELECT value || CASE WHEN hr THEN '{}'::jsonb ELSE jsonb_build_object(
 'schemas',(SELECT jsonb_object_agg(nspname,jsonb_build_object('owner',pg_get_userbyid(nspowner),'acl',pg_temp.employee_acl(nspacl)) ORDER BY nspname) FROM pg_namespace WHERE nspname IN('public','private','auth','storage')),
 'roles',(SELECT jsonb_agg(to_jsonb(r)-'oid'-'rolpassword' ORDER BY rolname) FROM pg_roles r),
 'memberships',coalesce((SELECT jsonb_agg(jsonb_build_array(pg_get_userbyid(roleid),pg_get_userbyid(member),pg_get_userbyid(grantor),admin_option,inherit_option,set_option) ORDER BY roleid,member,grantor) FROM pg_auth_members),'[]'),
 'defaultAcl',coalesce((SELECT jsonb_agg(jsonb_build_array(pg_get_userbyid(defaclrole),CASE WHEN defaclnamespace=0 THEN NULL ELSE defaclnamespace::regnamespace::text END,defaclobjtype,pg_temp.employee_acl(defaclacl)) ORDER BY defaclrole,defaclnamespace,defaclobjtype) FROM pg_default_acl),'[]'),
 'settings',coalesce((SELECT jsonb_agg(jsonb_build_array(CASE WHEN setdatabase=0 THEN NULL ELSE (SELECT datname FROM pg_database WHERE oid=setdatabase) END,CASE WHEN setrole=0 THEN NULL ELSE pg_get_userbyid(setrole) END,setconfig) ORDER BY setdatabase,setrole) FROM pg_db_role_setting WHERE setdatabase=0 OR setdatabase=(SELECT oid FROM pg_database WHERE datname=current_database())),'[]'),
 'database',(SELECT jsonb_build_object('name',datname,'owner',pg_get_userbyid(datdba),'acl',pg_temp.employee_acl(datacl)) FROM pg_database WHERE datname=current_database()),
 'extensions',(SELECT jsonb_agg(jsonb_build_array(extname,extversion,pg_get_userbyid(extowner),extnamespace::regnamespace::text) ORDER BY extname) FROM pg_extension)
 ) END FROM bodies
$catalog$;
-- Retained HR equality only. No row output or destructive recovery.
CREATE OR REPLACE FUNCTION pg_temp.employee_retained_data() RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog,pg_temp AS $$
DECLARE t text; result jsonb:='{}'; v jsonb; BEGIN
 FOREACH t IN ARRAY pg_temp.employee_tables() LOOP
 EXECUTE format('SELECT jsonb_build_object(''count'',count(*),''sha256'',encode(sha256(convert_to(coalesce(string_agg(to_jsonb(r)::text,E''\\n'' ORDER BY to_jsonb(r)::text COLLATE "C"),''''),''UTF8'')),''hex'')) FROM %s r',t) INTO v;
 result:=result||jsonb_build_object(t,v); END LOOP; RETURN result;
END $$;
-- Exact shared effective-permission assertions; never repairs a role or grant.
-- PostgreSQL 17 SET includes transitively reachable roles, even without INHERIT.
-- PUBLIC is a pseudo-role and must never be passed to pg_has_role.
CREATE OR REPLACE FUNCTION pg_temp.employee_effective_roles(app_role name)
RETURNS name[] LANGUAGE plpgsql STABLE SET search_path=pg_catalog AS $$
DECLARE roles name[];
BEGIN
 IF app_role='public' THEN RETURN ARRAY['public']::name[]; END IF;
 IF app_role IS NULL OR NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname=app_role)
 THEN RAISE EXCEPTION 'EMPLOYEE_UNKNOWN_EFFECTIVE_ROLE'; END IF;
 SELECT array_agg(rolname ORDER BY rolname COLLATE "C") INTO roles FROM pg_roles
 WHERE rolname=app_role OR pg_has_role(app_role,oid,'SET');
 RETURN roles;
END $$;
CREATE OR REPLACE FUNCTION pg_temp.employee_unsafe_table_access(app_role name)
RETURNS boolean LANGUAGE sql STABLE SET search_path=pg_catalog AS $$
 SELECT app_role IS NULL OR EXISTS(SELECT 1 FROM unnest(pg_temp.employee_tables()) t
  CROSS JOIN unnest(pg_temp.employee_effective_roles(app_role)) effective_role
  WHERE to_regclass(t) IS NULL
   OR has_table_privilege(effective_role,to_regclass(t),'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER,MAINTAIN') IS DISTINCT FROM false
   OR has_any_column_privilege(effective_role,to_regclass(t),'SELECT,INSERT,UPDATE,REFERENCES') IS DISTINCT FROM false)
$$;
-- Exact current-role grant is required only for authenticated's active entrypoints.
-- Switching to a narrower role is harmless; widening a denied surface is not.
CREATE OR REPLACE FUNCTION pg_temp.employee_function_access_safe(app_role name,effective_role name,mode text,is_entrypoint boolean,can_execute boolean)
RETURNS boolean LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$
 SELECT coalesce(app_role IN('public','anon','authenticated','service_role')
  AND effective_role IS NOT NULL AND mode IN('active','disabled')
  AND is_entrypoint IS NOT NULL AND can_execute IS NOT NULL
  AND CASE WHEN is_entrypoint AND mode='active' AND app_role='authenticated'
   THEN effective_role<>app_role OR can_execute
   ELSE NOT can_execute END,false)
$$;
CREATE OR REPLACE FUNCTION pg_temp.employee_assert_effective(mode text)
RETURNS void LANGUAGE plpgsql SET search_path=pg_catalog,pg_temp AS $$
DECLARE r name; effective_role name; f text;
BEGIN
 IF mode NOT IN('active','disabled') OR mode IS NULL THEN RAISE EXCEPTION 'EMPLOYEE_INVALID_EFFECTIVE_MODE'; END IF;
 FOREACH r IN ARRAY ARRAY['public','anon','authenticated','service_role']::name[] LOOP
  IF pg_temp.employee_unsafe_table_access(r) THEN RAISE EXCEPTION 'EMPLOYEE_UNSAFE_EFFECTIVE_TABLE_ACCESS'; END IF;
  FOREACH effective_role IN ARRAY pg_temp.employee_effective_roles(r) LOOP
   FOREACH f IN ARRAY pg_temp.employee_helpers() LOOP
    IF to_regprocedure(f) IS NULL OR NOT pg_temp.employee_function_access_safe(r,effective_role,mode,false,has_function_privilege(effective_role,to_regprocedure(f),'EXECUTE'))
    THEN RAISE EXCEPTION 'EMPLOYEE_UNSAFE_EFFECTIVE_HELPER_ACCESS'; END IF;
   END LOOP;
   FOREACH f IN ARRAY pg_temp.employee_entrypoints() LOOP
    IF to_regprocedure(f) IS NULL OR NOT pg_temp.employee_function_access_safe(r,effective_role,mode,true,has_function_privilege(effective_role,to_regprocedure(f),'EXECUTE'))
    THEN RAISE EXCEPTION 'EMPLOYEE_UNSAFE_EFFECTIVE_ENTRYPOINT_ACCESS'; END IF;
   END LOOP;
  END LOOP;
 END LOOP;
END $$;
CREATE OR REPLACE FUNCTION pg_temp.employee_assert_known(mode text) RETURNS void LANGUAGE plpgsql AS $known$
DECLARE observed text:=encode(sha256(convert_to(pg_temp.employee_catalog(true)::text,'UTF8')),'hex'); BEGIN
 IF EXISTS(SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname IN('public','private') AND p.proname LIKE 'employee\_%' ESCAPE '\' AND NOT pg_temp.employee_owned_object('pg_proc'::regclass,p.oid))
 OR EXISTS(SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN('public','private') AND c.relname LIKE 'employee\_%' ESCAPE '\' AND NOT pg_temp.employee_owned_object('pg_class'::regclass,c.oid))
 OR EXISTS(SELECT 1 FROM pg_type t JOIN pg_namespace n ON n.oid=t.typnamespace WHERE n.nspname IN('public','private') AND (t.typname LIKE 'employee\_%' ESCAPE '\' OR t.typname LIKE '\_employee\_%' ESCAPE '\') AND NOT pg_temp.employee_owned_object('pg_type'::regclass,t.oid))
 OR NOT ((mode IN('active','either') AND observed='1de0753eae6104e022ac776cc7be03d828cf28c87d8972faf4141a44c740a516') OR (mode IN('disabled','either') AND observed='87c0e460a38d8e3c8f106953d189e80dd05b9287910d7947c01a261f9f4ed67e')) THEN RAISE EXCEPTION 'EMPLOYEE_UNKNOWN_TOPOLOGY_OR_ACL'; END IF;
 PERFORM pg_temp.employee_assert_effective(CASE WHEN observed='1de0753eae6104e022ac776cc7be03d828cf28c87d8972faf4141a44c740a516' THEN 'active' ELSE 'disabled' END);
END $known$;
DO $absent$ BEGIN
 IF NOT EXISTS(SELECT 1 FROM pg_namespace WHERE nspname='private') OR to_regclass('public.users') IS NULL OR to_regprocedure('auth.uid()') IS NULL
 OR EXISTS(SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN('public','private') AND c.relname LIKE 'employee\_%' ESCAPE '\')
 OR EXISTS(SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname IN('public','private') AND p.proname LIKE 'employee\_%' ESCAPE '\')
 OR EXISTS(SELECT 1 FROM pg_type t JOIN pg_namespace n ON n.oid=t.typnamespace WHERE n.nspname IN('public','private') AND (t.typname LIKE 'employee\_%' ESCAPE '\' OR t.typname LIKE '\_employee\_%' ESCAPE '\'))
 THEN RAISE EXCEPTION 'EMPLOYEE_INSTALL_REQUIRES_ABSENT_TOPOLOGY'; END IF;
END $absent$;
CREATE TEMP TABLE employee_activation_legacy ON COMMIT DROP AS SELECT pg_temp.employee_catalog(false) value;
-- UNPUBLISHED CANDIDATE. No hosted execution, live activation, data import or role grants.
-- DO NOT RUN DIRECTLY. Transaction-neutral source for fixed disposable test wrappers.
-- A future atomic activation bundle requires separate review and authorization.
-- Employee identity is separate from users, leave membership, access and reporting routing.
SET LOCAL search_path = pg_catalog, pg_temp;
CREATE SCHEMA IF NOT EXISTS private;

CREATE FUNCTION private.employee_timezone_valid(p_zone text) RETURNS boolean
LANGUAGE sql STABLE SET search_path = pg_catalog, pg_temp AS $$
 SELECT p_zone IS NULL OR (p_zone=btrim(p_zone) AND (p_zone='UTC' OR position('/' IN p_zone)>0)
  AND p_zone NOT LIKE 'posix/%' AND p_zone NOT LIKE 'right/%'
  AND EXISTS(SELECT 1 FROM pg_catalog.pg_timezone_names WHERE name=p_zone));
$$;
CREATE TABLE private.employee_settings (
 singleton boolean PRIMARY KEY DEFAULT true CHECK(singleton),
 timezone text CHECK(private.employee_timezone_valid(timezone)),
 version bigint NOT NULL DEFAULT 1 CHECK(version BETWEEN 1 AND 9007199254740991)
);
INSERT INTO private.employee_settings(singleton) VALUES(true);
CREATE TABLE private.employee_reporting_guard (
 singleton boolean PRIMARY KEY DEFAULT true CHECK(singleton),
 revision bigint NOT NULL DEFAULT 0 CHECK(revision BETWEEN 0 AND 9007199254740991)
);
INSERT INTO private.employee_reporting_guard(singleton) VALUES(true);
CREATE TABLE private.employee_records (
 id uuid PRIMARY KEY,
 version bigint NOT NULL DEFAULT 1 CHECK(version BETWEEN 1 AND 9007199254740991),
 name text NOT NULL CHECK(name=btrim(name) AND char_length(name) BETWEEN 1 AND 160),
 employee_number text CHECK(employee_number=btrim(employee_number) AND char_length(employee_number) BETWEEN 1 AND 64),
 job_title text CHECK(job_title=btrim(job_title) AND char_length(job_title) BETWEEN 1 AND 120),
 team text CHECK(team=btrim(team) AND char_length(team) BETWEEN 1 AND 120),
 recorded_status text NOT NULL DEFAULT 'draft' CHECK(recorded_status IN('draft','active','ended')),
 reporting_revision bigint NOT NULL DEFAULT 0 CHECK(reporting_revision BETWEEN 0 AND 9007199254740991),
 created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 updated_at timestamptz NOT NULL DEFAULT clock_timestamp()
);
CREATE INDEX employee_records_name_id ON private.employee_records(name COLLATE "C",id);
CREATE UNIQUE INDEX employee_records_current_number ON private.employee_records(lower(employee_number)) WHERE employee_number IS NOT NULL;
CREATE TABLE private.employee_number_claims (
 normalized_number text PRIMARY KEY CHECK(normalized_number=lower(btrim(normalized_number)) AND char_length(normalized_number) BETWEEN 1 AND 64),
 employee_id uuid NOT NULL REFERENCES private.employee_records(id) ON DELETE RESTRICT,
 claimed_at timestamptz NOT NULL DEFAULT clock_timestamp()
);
CREATE INDEX employee_number_claims_employee ON private.employee_number_claims(employee_id);
CREATE TABLE private.employee_account_links (
 user_id uuid PRIMARY KEY REFERENCES public.users(id) ON DELETE RESTRICT,
 employee_id uuid UNIQUE NOT NULL REFERENCES private.employee_records(id) ON DELETE RESTRICT,
 quarantined boolean NOT NULL DEFAULT false,
 linked_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 quarantined_at timestamptz
);
CREATE TABLE private.employee_episodes (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
 employee_id uuid UNIQUE NOT NULL REFERENCES private.employee_records(id) ON DELETE RESTRICT,
 episode_number integer NOT NULL DEFAULT 1 CHECK(episode_number=1),
 start_date date CHECK(start_date IS NULL OR (isfinite(start_date) AND start_date BETWEEN '0001-01-01'::date AND '9999-12-31'::date)),
 end_date date CHECK(end_date IS NULL OR (isfinite(end_date) AND end_date BETWEEN '0001-01-01'::date AND '9999-12-31'::date)),
 source_reference text CHECK(source_reference=btrim(source_reference) AND char_length(source_reference) BETWEEN 1 AND 500),
 CHECK(start_date IS NULL OR end_date IS NULL OR end_date>=start_date)
);
CREATE TABLE private.employee_reporting_revisions (
 employee_id uuid NOT NULL REFERENCES private.employee_records(id) ON DELETE RESTRICT,
 revision bigint NOT NULL CHECK(revision BETWEEN 1 AND 9007199254740991),
 mode text NOT NULL CHECK(mode IN('schedule','correction')),
 actor_id uuid NOT NULL REFERENCES public.users(id) ON DELETE RESTRICT,
 recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 source_reference text CHECK(source_reference=btrim(source_reference) AND char_length(source_reference) BETWEEN 1 AND 500),
 PRIMARY KEY(employee_id,revision)
);
CREATE TABLE private.employee_reporting_intervals (
 employee_id uuid NOT NULL,
 revision bigint NOT NULL,
 ordinal integer NOT NULL CHECK(ordinal>=0),
 manager_employee_id uuid REFERENCES private.employee_records(id) ON DELETE RESTRICT,
 from_date date NOT NULL CHECK(isfinite(from_date) AND from_date BETWEEN '0001-01-01'::date AND '9999-12-31'::date),
 until_date date CHECK(until_date IS NULL OR (isfinite(until_date) AND until_date BETWEEN '0001-01-01'::date AND '9999-12-31'::date)),
 PRIMARY KEY(employee_id,revision,ordinal),
 FOREIGN KEY(employee_id,revision) REFERENCES private.employee_reporting_revisions(employee_id,revision) ON DELETE RESTRICT,
 CHECK(manager_employee_id IS NULL OR manager_employee_id<>employee_id),
 CHECK(until_date IS NULL OR until_date>from_date)
);
CREATE INDEX employee_reporting_intervals_manager ON private.employee_reporting_intervals(manager_employee_id,from_date,until_date);
CREATE TABLE private.employee_audit_events (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
 employee_id uuid NOT NULL REFERENCES private.employee_records(id) ON DELETE RESTRICT,
 actor_id uuid NOT NULL REFERENCES public.users(id) ON DELETE RESTRICT,
 actor_name text NOT NULL,
 recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 effective_date date CHECK(effective_date IS NULL OR (isfinite(effective_date) AND effective_date BETWEEN '0001-01-01'::date AND '9999-12-31'::date)),
 action text NOT NULL CHECK(action IN('create_employee','edit_employee','save_initial_episode','link_account','quarantine_account_link','save_reporting')),
 reason text NOT NULL CHECK(reason=btrim(reason) AND char_length(reason) BETWEEN 1 AND 500),
 source_reference text CHECK(source_reference=btrim(source_reference) AND char_length(source_reference) BETWEEN 1 AND 500),
 before_data jsonb NOT NULL DEFAULT '{}' CHECK(jsonb_typeof(before_data)='object'),
 after_data jsonb NOT NULL DEFAULT '{}' CHECK(jsonb_typeof(after_data)='object')
);
CREATE INDEX employee_audit_employee_time ON private.employee_audit_events(employee_id,recorded_at DESC,id DESC);
-- A tombstone may precede employee creation. No FK is appropriate for its target UUID.
-- A pending command is never committed: atomic command + audit + result or no change.
CREATE TABLE private.employee_operations (
 actor_id uuid NOT NULL REFERENCES public.users(id) ON DELETE RESTRICT,
 operation_id uuid NOT NULL,
 employee_id uuid,
 action text,
 expected_version bigint CHECK(expected_version BETWEEN 0 AND 9007199254740991),
 request_fingerprint text,
 state text NOT NULL CHECK(state IN('completed','abandoned')),
 result jsonb CHECK(result IS NULL OR jsonb_typeof(result)='object'),
 recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 PRIMARY KEY(actor_id,operation_id),
 CHECK((state='completed' AND result IS NOT NULL AND request_fingerprint IS NOT NULL) OR (state='abandoned' AND result IS NULL))
);

-- No client table access, even when service_role can bypass row policies.
DO $$ DECLARE t text; BEGIN
 FOREACH t IN ARRAY ARRAY['employee_records','employee_number_claims','employee_account_links','employee_episodes',
  'employee_reporting_revisions','employee_reporting_intervals','employee_audit_events','employee_operations','employee_settings','employee_reporting_guard'] LOOP
  EXECUTE format('ALTER TABLE private.%I ENABLE ROW LEVEL SECURITY',t);
  EXECUTE format('REVOKE ALL ON TABLE private.%I FROM PUBLIC, anon, authenticated, service_role',t);
 END LOOP;
END $$;

CREATE FUNCTION private.employee_require_director() RETURNS uuid
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$
DECLARE actor uuid:=auth.uid();
BEGIN
 IF actor IS NULL OR NOT EXISTS(SELECT 1 FROM public.users WHERE id=actor AND is_active AND role='executive') THEN
  RAISE EXCEPTION 'Employee Director authority required' USING ERRCODE='42501';
 END IF;
 RETURN actor;
END;
$$;
CREATE FUNCTION private.employee_read_guard(p_query text,p_page integer,p_page_size integer) RETURNS text
LANGUAGE plpgsql IMMUTABLE SET search_path = pg_catalog, pg_temp AS $$
BEGIN
 IF p_page IS NULL OR p_page<1 OR p_page_size IS NULL OR p_page_size NOT BETWEEN 1 AND 100
  OR p_query IS NULL OR char_length(btrim(p_query))>120 THEN
  RAISE EXCEPTION 'Invalid employee page input' USING ERRCODE='22023';
 END IF;
 RETURN btrim(p_query);
END;
$$;
CREATE FUNCTION private.employee_fields(p_row private.employee_records) RETURNS jsonb
LANGUAGE sql IMMUTABLE SET search_path = pg_catalog, pg_temp AS $$
 SELECT jsonb_build_object('name',p_row.name,'employeeNumber',p_row.employee_number,'jobTitle',p_row.job_title,
  'team',p_row.team,'recordedStatus',p_row.recorded_status);
$$;
-- Defense in depth: never return arbitrary stored JSON, including nested extras.
CREATE FUNCTION private.employee_audit_projection(p_data jsonb) RETURNS jsonb
LANGUAGE plpgsql IMMUTABLE SET search_path = pg_catalog, pg_temp AS $$
DECLARE result jsonb:='{}'; section text; keys text[]; projected jsonb;
BEGIN
 FOREACH section IN ARRAY ARRAY['fields','episode','account'] LOOP
  keys:=CASE section WHEN 'fields' THEN ARRAY['name','employeeNumber','jobTitle','team','recordedStatus']
   WHEN 'episode' THEN ARRAY['startDate','endDate','sourceReference'] ELSE ARRAY['userId'] END;
  IF jsonb_typeof(p_data->section)='object' THEN
   SELECT coalesce(jsonb_object_agg(key,value),'{}') INTO projected FROM jsonb_each(p_data->section) WHERE key=ANY(keys)
    AND jsonb_typeof(value) IN('string','null');
   result:=result||jsonb_build_object(section,projected);
  END IF;
 END LOOP;
 IF jsonb_typeof(p_data->'reporting')='array' THEN
  SELECT coalesce(jsonb_agg((SELECT coalesce(jsonb_object_agg(key,value),'{}') FROM jsonb_each(item)
   WHERE key IN('managerEmployeeId','from','until') AND jsonb_typeof(value) IN('string','null')) ORDER BY ordinal),'[]')
  INTO projected FROM jsonb_array_elements(p_data->'reporting') WITH ORDINALITY AS items(item,ordinal) WHERE jsonb_typeof(item)='object';
  result:=result||jsonb_build_object('reporting',projected);
 END IF;
 RETURN result;
END;
$$;
CREATE FUNCTION private.employee_context_impl_v1() RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$
DECLARE actor uuid:=auth.uid(); allowed boolean; zone text; config_version bigint; profile_stamp text;
BEGIN
 IF actor IS NULL THEN RAISE EXCEPTION 'Authenticated actor required' USING ERRCODE='42501'; END IF;
 SELECT u.is_active AND u.role='executive',u.role::text||':'||u.is_active::text||':'||u.xmin::text
 INTO allowed,profile_stamp FROM public.users u WHERE id=actor;
 SELECT s.timezone,s.version INTO zone,config_version FROM private.employee_settings s WHERE singleton;
 RETURN jsonb_build_object('actorId',actor,'scopeVersion',md5(actor::text||':'||coalesce(profile_stamp,'missing')||':'||config_version::text||':'||coalesce(zone,'')),
  'canMaintainBasic',coalesce(allowed,false),'timezone',CASE WHEN allowed THEN zone END,
  'today',CASE WHEN allowed AND zone IS NOT NULL THEN to_char(statement_timestamp() AT TIME ZONE zone,'YYYY-MM-DD') END,
  'setupBlockers',CASE WHEN allowed AND zone IS NULL THEN '["WORKPLACE_TIMEZONE_UNCONFIRMED"]'::jsonb ELSE '[]'::jsonb END);
END;
$$;
CREATE FUNCTION private.employee_page_impl_v1(p_query text,p_status text,p_page integer,p_page_size integer) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$
DECLARE q text; result_rows jsonb; row_total bigint;
BEGIN
 PERFORM private.employee_require_director();
 q:=private.employee_read_guard(p_query,p_page,p_page_size);
 IF p_status IS NOT NULL AND p_status NOT IN('draft','active','ended') THEN RAISE EXCEPTION 'Invalid employee status' USING ERRCODE='22023'; END IF;
 WITH matches AS MATERIALIZED (SELECT e.* FROM private.employee_records e WHERE (p_status IS NULL OR e.recorded_status=p_status)
  AND (q='' OR strpos(lower(e.name),lower(q))>0 OR strpos(lower(coalesce(e.employee_number,'')),lower(q))>0)),
 page_rows AS (SELECT * FROM matches ORDER BY name COLLATE "C",id LIMIT p_page_size OFFSET (p_page::bigint-1)*p_page_size)
 SELECT (SELECT count(*) FROM matches),coalesce(jsonb_agg(jsonb_build_object('id',r.id,'version',r.version)||private.employee_fields(r::private.employee_records)
  ORDER BY r.name COLLATE "C",r.id),'[]') INTO row_total,result_rows FROM page_rows r;
 RETURN jsonb_build_object('rows',result_rows,'total',row_total,'page',p_page,'pageSize',p_page_size);
END;
$$;
CREATE FUNCTION private.employee_detail_impl_v1(p_employee_id uuid) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$
DECLARE employee private.employee_records%ROWTYPE; episode jsonb; account jsonb; reporting jsonb; warnings jsonb:='[]';
 linked private.employee_account_links%ROWTYPE; account_user public.users%ROWTYPE; zone text; today date;
 current_manager uuid; manager_user uuid; manager_quarantined boolean; has_interval boolean;
BEGIN
 PERFORM private.employee_require_director();
 IF p_employee_id IS NULL THEN RAISE EXCEPTION 'Employee id required' USING ERRCODE='22023'; END IF;
 SELECT * INTO employee FROM private.employee_records WHERE id=p_employee_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'Employee not found' USING ERRCODE='P0002'; END IF;
 SELECT jsonb_build_object('startDate',start_date,'endDate',end_date,'sourceReference',source_reference) INTO episode
 FROM private.employee_episodes WHERE employee_id=p_employee_id;
 SELECT * INTO linked FROM private.employee_account_links WHERE employee_id=p_employee_id;
 IF FOUND THEN
  SELECT * INTO account_user FROM public.users WHERE id=linked.user_id;
  account:=jsonb_build_object('userId',account_user.id,'displayName',account_user.full_name,'email',account_user.email,
   'role',account_user.role,'active',account_user.is_active,'operationalManagerId',account_user.manager_id,
   'operationalManagerName',(SELECT full_name FROM public.users WHERE id=account_user.manager_id),'quarantined',linked.quarantined);
  IF employee.recorded_status='ended' AND account_user.is_active THEN warnings:=warnings||'"ENDED_EMPLOYMENT_ACTIVE_LOGIN"'::jsonb; END IF;
  IF employee.recorded_status='active' AND NOT account_user.is_active THEN warnings:=warnings||'"ACTIVE_EMPLOYMENT_INACTIVE_LOGIN"'::jsonb; END IF;
  IF linked.quarantined THEN warnings:=warnings||'"ACCOUNT_LINK_QUARANTINED"'::jsonb; END IF;
 END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('managerEmployeeId',manager_employee_id,'from',from_date,'until',until_date)
  ORDER BY from_date,ordinal),'[]') INTO reporting FROM private.employee_reporting_intervals
 WHERE employee_id=p_employee_id AND revision=employee.reporting_revision;
 IF account IS NOT NULL THEN
  SELECT timezone INTO zone FROM private.employee_settings WHERE singleton;
  IF zone IS NULL THEN warnings:=warnings||'"REPORTING_COMPARISON_UNAVAILABLE"'::jsonb;
  ELSE
   today:=(statement_timestamp() AT TIME ZONE zone)::date;
   SELECT manager_employee_id,true INTO current_manager,has_interval FROM private.employee_reporting_intervals
   WHERE employee_id=p_employee_id AND revision=employee.reporting_revision AND from_date<=today AND (until_date IS NULL OR today<until_date)
   ORDER BY from_date,ordinal LIMIT 1;
   IF NOT coalesce(has_interval,false) THEN warnings:=warnings||'"REPORTING_COMPARISON_UNAVAILABLE"'::jsonb;
   ELSE
    SELECT user_id,quarantined INTO manager_user,manager_quarantined FROM private.employee_account_links WHERE employee_id=current_manager;
    IF linked.quarantined OR (current_manager IS NOT NULL AND (manager_user IS NULL OR manager_quarantined)) THEN
     warnings:=warnings||'"REPORTING_ACCESS_MANAGER_UNCOMPARABLE"'::jsonb;
    ELSIF manager_user IS DISTINCT FROM account_user.manager_id THEN warnings:=warnings||'"REPORTING_ACCESS_MANAGER_MISMATCH"'::jsonb;
    END IF;
   END IF;
  END IF;
 END IF;
 RETURN jsonb_build_object('id',employee.id,'version',employee.version,'fields',private.employee_fields(employee),
  'episode',episode,'account',account,'reportingRevision',employee.reporting_revision,'reporting',reporting,'warnings',warnings);
END;
$$;
CREATE FUNCTION private.employee_audit_impl_v1(p_employee_id uuid,p_page integer,p_page_size integer) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$
DECLARE result_rows jsonb; row_total bigint;
BEGIN
 PERFORM private.employee_require_director(); PERFORM private.employee_read_guard('',p_page,p_page_size);
 IF p_employee_id IS NULL THEN RAISE EXCEPTION 'Employee id required' USING ERRCODE='22023'; END IF;
 IF NOT EXISTS(SELECT 1 FROM private.employee_records WHERE id=p_employee_id) THEN RAISE EXCEPTION 'Employee not found' USING ERRCODE='P0002'; END IF;
 SELECT count(*) INTO row_total FROM private.employee_audit_events WHERE employee_id=p_employee_id;
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',a.id,'employeeId',a.employee_id,'actorId',a.actor_id,'actorName',a.actor_name,
  'recordedAt',to_char(a.recorded_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'effectiveDate',a.effective_date,
  'action',a.action,'reason',a.reason,'sourceReference',a.source_reference,
  'before',private.employee_audit_projection(a.before_data),'after',private.employee_audit_projection(a.after_data))
  ORDER BY a.recorded_at DESC,a.id DESC),'[]') INTO result_rows FROM
  (SELECT * FROM private.employee_audit_events WHERE employee_id=p_employee_id ORDER BY recorded_at DESC,id DESC
   LIMIT p_page_size OFFSET (p_page::bigint-1)*p_page_size) a;
 RETURN jsonb_build_object('rows',result_rows,'total',row_total,'page',p_page,'pageSize',p_page_size);
END;
$$;
CREATE FUNCTION private.employee_account_candidates_impl_v1(p_query text,p_page integer,p_page_size integer) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$
DECLARE q text; result_rows jsonb; row_total bigint;
BEGIN
 PERFORM private.employee_require_director(); q:=private.employee_read_guard(p_query,p_page,p_page_size);
 WITH matches AS MATERIALIZED (SELECT u.id,u.full_name,u.email,u.role,u.is_active,
   CASE WHEN l.quarantined THEN 'quarantined' WHEN l.user_id IS NOT NULL THEN 'linked' ELSE 'unlinked' END link_state
  FROM public.users u LEFT JOIN private.employee_account_links l ON l.user_id=u.id
  WHERE q='' OR strpos(lower(u.full_name),lower(q))>0 OR strpos(lower(u.email),lower(q))>0),
 page_rows AS (SELECT * FROM matches ORDER BY full_name COLLATE "C",id LIMIT p_page_size OFFSET (p_page::bigint-1)*p_page_size)
 SELECT (SELECT count(*) FROM matches),coalesce(jsonb_agg(jsonb_build_object('userId',r.id,'displayName',r.full_name,
  'email',r.email,'role',r.role,'active',r.is_active,'linkState',r.link_state) ORDER BY r.full_name COLLATE "C",r.id),'[]')
 INTO row_total,result_rows FROM page_rows r;
 RETURN jsonb_build_object('rows',result_rows,'total',row_total,'page',p_page,'pageSize',p_page_size);
END;
$$;

-- Public invoker wrappers expose only the narrow versioned APIs. Every privileged
-- implementation independently checks current users authority, not editable claims.
CREATE FUNCTION public.employee_context_v1() RETURNS jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path = pg_catalog, pg_temp
AS $$ SELECT private.employee_context_impl_v1(); $$;
CREATE FUNCTION public.employee_page_v1(p_query text,p_status text,p_page integer,p_page_size integer) RETURNS jsonb
LANGUAGE sql STABLE SECURITY INVOKER SET search_path = pg_catalog, pg_temp
AS $$ SELECT private.employee_page_impl_v1(p_query,p_status,p_page,p_page_size); $$;
CREATE FUNCTION public.employee_detail_v1(p_employee_id uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path = pg_catalog, pg_temp
AS $$ SELECT private.employee_detail_impl_v1(p_employee_id); $$;
CREATE FUNCTION public.employee_audit_v1(p_employee_id uuid,p_page integer,p_page_size integer) RETURNS jsonb
LANGUAGE sql STABLE SECURITY INVOKER SET search_path = pg_catalog, pg_temp
AS $$ SELECT private.employee_audit_impl_v1(p_employee_id,p_page,p_page_size); $$;
CREATE FUNCTION public.employee_account_candidates_v1(p_query text,p_page integer,p_page_size integer) RETURNS jsonb
LANGUAGE sql STABLE SECURITY INVOKER SET search_path = pg_catalog, pg_temp
AS $$ SELECT private.employee_account_candidates_impl_v1(p_query,p_page,p_page_size); $$;

-- Close default PUBLIC execution in the creation transaction. Do not alter unrelated
-- schema defaults or privileges of existing leave/calendar functions.
DO $$ DECLARE f record; BEGIN
 FOR f IN SELECT p.oid::regprocedure signature FROM pg_catalog.pg_proc p JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace
 WHERE n.nspname IN('public','private') AND p.proname LIKE 'employee\_%' ESCAPE '\' LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC, anon, authenticated, service_role',f.signature);
 END LOOP;
END $$;
GRANT USAGE ON SCHEMA private TO authenticated;
GRANT EXECUTE ON FUNCTION private.employee_context_impl_v1(),private.employee_page_impl_v1(text,text,integer,integer),
 private.employee_detail_impl_v1(uuid),private.employee_audit_impl_v1(uuid,integer,integer),private.employee_account_candidates_impl_v1(text,integer,integer),
 public.employee_context_v1(),public.employee_page_v1(text,text,integer,integer),public.employee_detail_v1(uuid),
 public.employee_audit_v1(uuid,integer,integer),public.employee_account_candidates_v1(text,integer,integer) TO authenticated;

-- UNPUBLISHED CANDIDATE. Transaction-neutral; fixed disposable wrappers only.
-- No account access, operational routing, leave, entitlement or invitation writes.
SET LOCAL search_path = pg_catalog, pg_temp;

-- Match ECMAScript String.trim(), then measure Unicode code points (char_length).
CREATE FUNCTION private.employee_trim(p_value text) RETURNS text
LANGUAGE sql IMMUTABLE SET search_path = pg_catalog, pg_temp AS $$
 SELECT btrim(p_value, chr(9)||chr(10)||chr(11)||chr(12)||chr(13)||chr(32)||chr(160)||chr(5760)||
  chr(8192)||chr(8193)||chr(8194)||chr(8195)||chr(8196)||chr(8197)||chr(8198)||chr(8199)||chr(8200)||chr(8201)||chr(8202)||
  chr(8232)||chr(8233)||chr(8239)||chr(8287)||chr(12288)||chr(65279));
$$;
CREATE FUNCTION private.employee_text(p_value text,p_limit integer,p_required boolean DEFAULT false) RETURNS text
LANGUAGE plpgsql IMMUTABLE SET search_path = pg_catalog, pg_temp AS $$
DECLARE value text:=nullif(private.employee_trim(p_value),'');
BEGIN
 IF (p_required AND value IS NULL) OR char_length(value)>p_limit THEN RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='22023'; END IF;
 RETURN value;
END;
$$;
CREATE FUNCTION private.employee_date(p_value jsonb) RETURNS date
LANGUAGE plpgsql IMMUTABLE SET search_path = pg_catalog, pg_temp AS $$
DECLARE value date; raw text;
BEGIN
 IF p_value='null'::jsonb THEN RETURN NULL; END IF;
 IF jsonb_typeof(p_value) IS DISTINCT FROM 'string' THEN RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='22023'; END IF;
 raw:=p_value#>>'{}';
 IF raw!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='22023'; END IF;
 BEGIN value:=raw::date; EXCEPTION WHEN datetime_field_overflow OR invalid_datetime_format THEN RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='22023'; END;
 IF NOT isfinite(value) OR value<'0001-01-01'::date OR value>'9999-12-31'::date OR to_char(value,'YYYY-MM-DD')<>raw THEN
  RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='22023'; END IF;
 RETURN value;
END;
$$;
CREATE FUNCTION private.employee_hash(p_value jsonb) RETURNS text
LANGUAGE sql IMMUTABLE SET search_path = pg_catalog, pg_temp AS $$ SELECT encode(sha256(convert_to(p_value::text,'UTF8')),'hex'); $$;

-- Pure normalization is deliberately independent of mutable employee/account state.
-- Completed same-ID replay compares this identity before state-dependent validation.
CREATE FUNCTION private.employee_request(p_employee_id uuid,p_expected_version bigint,p_action text,p_payload jsonb,
 p_reason text,p_effective_date date,p_source_reference text) RETURNS jsonb
LANGUAGE plpgsql IMMUTABLE SET search_path = pg_catalog, pg_temp AS $$
DECLARE keys text[]; key text; normalized jsonb:='{}'; value text; start_date date; end_date date; account uuid;
 reason text; source text; episode_source text;
BEGIN
 IF p_action='add_employment_episode' THEN RAISE EXCEPTION 'REHIRE_DEFERRED' USING ERRCODE='22023'; END IF;
 IF p_action IS NULL OR p_action NOT IN('create_employee','edit_employee','save_initial_episode','link_account','quarantine_account_link','save_reporting') THEN
  RAISE EXCEPTION 'INVALID_ACTION' USING ERRCODE='22023'; END IF;
 IF p_employee_id IS NULL OR p_expected_version IS NULL OR p_expected_version NOT BETWEEN 0 AND 9007199254740991
  OR jsonb_typeof(p_payload) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='22023'; END IF;
 reason:=private.employee_text(p_reason,500,true); source:=private.employee_text(p_source_reference,500);
 IF p_effective_date IS NOT NULL AND (NOT isfinite(p_effective_date) OR p_effective_date NOT BETWEEN '0001-01-01'::date AND '9999-12-31'::date) THEN
  RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='22023'; END IF;
 keys:=CASE WHEN p_action IN('create_employee','edit_employee') THEN ARRAY['name','employeeNumber','jobTitle','team','recordedStatus']
  WHEN p_action='save_initial_episode' THEN ARRAY['startDate','endDate','sourceReference']
  WHEN p_action='save_reporting' THEN ARRAY['mode','intervals'] ELSE ARRAY['userId'] END;
 IF NOT p_payload?&keys OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_payload) k WHERE NOT k=ANY(keys)) THEN
  RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='22023'; END IF;
 FOREACH key IN ARRAY keys LOOP
  IF p_action<>'save_reporting' AND jsonb_typeof(p_payload->key) NOT IN('string','null') THEN RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='22023'; END IF;
 END LOOP;
 IF p_action IN('create_employee','edit_employee') THEN
  normalized:=jsonb_build_object('name',private.employee_text(p_payload->>'name',160,true),
   'employeeNumber',private.employee_text(p_payload->>'employeeNumber',64),'jobTitle',private.employee_text(p_payload->>'jobTitle',120),
   'team',private.employee_text(p_payload->>'team',120),'recordedStatus',p_payload->>'recordedStatus');
  IF p_payload->>'recordedStatus' IS NULL OR p_payload->>'recordedStatus' NOT IN('draft','active','ended') THEN RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='22023'; END IF;
 ELSIF p_action='save_initial_episode' THEN
  start_date:=private.employee_date(p_payload->'startDate'); end_date:=private.employee_date(p_payload->'endDate');
  IF end_date<start_date THEN RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='22023'; END IF;
  episode_source:=private.employee_text(p_payload->>'sourceReference',500);
  IF episode_source IS NOT NULL AND source IS NOT NULL AND episode_source<>source THEN RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='22023'; END IF;
  normalized:=jsonb_build_object('startDate',to_char(start_date,'YYYY-MM-DD'),'endDate',to_char(end_date,'YYYY-MM-DD'),'sourceReference',episode_source);
 ELSIF p_action='save_reporting' THEN
  normalized:=private.employee_reporting_request(p_employee_id,p_payload);
  IF normalized->>'mode'='correction' AND source IS NULL THEN RAISE EXCEPTION 'CORRECTION_SOURCE_REQUIRED' USING ERRCODE='22023'; END IF;
 ELSE
  value:=p_payload->>'userId';
  IF value IS NULL OR value!~*'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='22023'; END IF;
  account:=value::uuid; normalized:=jsonb_build_object('userId',account);
 END IF;
 RETURN jsonb_build_object('employeeId',p_employee_id,'expectedVersion',p_expected_version,'action',p_action,'payload',normalized,
  'reason',reason,'effectiveDate',to_char(p_effective_date,'YYYY-MM-DD'),'sourceReference',source);
END;
$$;
CREATE FUNCTION private.employee_lock_actor() RETURNS uuid
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$
DECLARE actor uuid:=auth.uid(); current_actor uuid;
BEGIN
 -- Lock and recheck the actual row after any concurrent deactivation finishes.
 SELECT id INTO current_actor FROM public.users WHERE id=actor AND is_active AND role='executive' FOR SHARE;
 IF current_actor IS NULL THEN RAISE EXCEPTION 'DIRECTOR_REQUIRED' USING ERRCODE='42501'; END IF;
 RETURN current_actor;
END;
$$;
CREATE FUNCTION private.employee_lock_operation(p_actor uuid,p_operation uuid) RETURNS void
LANGUAGE sql VOLATILE SET search_path = pg_catalog, pg_temp AS $$
 SELECT pg_advisory_xact_lock(hashtextextended('employee-operation:'||p_actor::text||':'||p_operation::text,0));
$$;

-- Shared state-dependent validator and preview composer. Commit calls only after
-- actor -> operation -> settings -> reporting graph (when needed) -> employee
-- -> selected account locks are held. Reporting helpers live in the next candidate.
CREATE FUNCTION private.employee_prepare(p_request jsonb) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SET search_path = pg_catalog, pg_temp AS $$
DECLARE target uuid:=(p_request->>'employeeId')::uuid; expected bigint:=(p_request->>'expectedVersion')::bigint;
 action text:=p_request->>'action'; payload jsonb:=p_request->'payload'; employee private.employee_records%ROWTYPE;
 config private.employee_settings%ROWTYPE; before_data jsonb:='{}'; after_data jsonb:='{}'; episode jsonb; selected jsonb;
 selected_id uuid; user_row public.users%ROWTYPE; linked private.employee_account_links%ROWTYPE; context jsonb; fingerprint text; reporting jsonb;
BEGIN
 SELECT * INTO config FROM private.employee_settings WHERE singleton;
 SELECT * INTO employee FROM private.employee_records WHERE id=target;
 IF action='create_employee' THEN
  IF employee.id IS NOT NULL THEN RAISE EXCEPTION 'EMPLOYEE_EXISTS' USING ERRCODE='23505'; END IF;
  IF expected<>0 THEN RAISE EXCEPTION 'VERSION_CONFLICT' USING ERRCODE='40001'; END IF;
 ELSE
  IF employee.id IS NULL THEN RAISE EXCEPTION 'EMPLOYEE_NOT_FOUND' USING ERRCODE='P0002'; END IF;
  IF employee.version<>expected OR employee.version=9007199254740991 THEN RAISE EXCEPTION 'VERSION_CONFLICT' USING ERRCODE='40001'; END IF;
 END IF;
 IF p_request->>'effectiveDate' IS NOT NULL AND config.timezone IS NULL THEN RAISE EXCEPTION 'WORKPLACE_TIMEZONE_UNCONFIRMED' USING ERRCODE='55000'; END IF;
 IF action IN('create_employee','edit_employee') THEN
  IF EXISTS(SELECT 1 FROM private.employee_number_claims WHERE normalized_number=lower(payload->>'employeeNumber') AND employee_id<>target) THEN
   RAISE EXCEPTION 'NUMBER_CLAIMED' USING ERRCODE='23505'; END IF;
  IF employee.id IS NOT NULL THEN before_data:=jsonb_build_object('fields',private.employee_fields(employee)); END IF;
  after_data:=jsonb_build_object('fields',payload);
 ELSIF action='save_initial_episode' THEN
  SELECT jsonb_build_object('startDate',to_char(start_date,'YYYY-MM-DD'),'endDate',to_char(end_date,'YYYY-MM-DD'),'sourceReference',source_reference)
   INTO episode FROM private.employee_episodes WHERE employee_id=target;
  IF config.timezone IS NULL AND (payload->>'startDate' IS NOT NULL OR payload->>'endDate' IS NOT NULL OR episode->>'startDate' IS NOT NULL OR episode->>'endDate' IS NOT NULL) THEN
   RAISE EXCEPTION 'WORKPLACE_TIMEZONE_UNCONFIRMED' USING ERRCODE='55000'; END IF;
  IF episode IS NOT NULL THEN before_data:=jsonb_build_object('episode',episode); END IF;
  after_data:=jsonb_build_object('episode',payload);
 ELSIF action='save_reporting' THEN
  reporting:=private.employee_reporting_prepare(p_request);
  before_data:=reporting->'before'; after_data:=reporting->'after';
 ELSE
  selected_id:=(payload->>'userId')::uuid;
  SELECT * INTO user_row FROM public.users WHERE id=selected_id;
  IF user_row.id IS NULL THEN RAISE EXCEPTION 'ACCOUNT_NOT_FOUND' USING ERRCODE='P0002'; END IF;
  SELECT * INTO linked FROM private.employee_account_links WHERE user_id=selected_id;
  selected:=jsonb_build_object('userId',user_row.id,'displayName',user_row.full_name,'email',user_row.email,'role',user_row.role,
   'active',user_row.is_active,'operationalManagerId',user_row.manager_id,
   'employeeId',linked.employee_id,'quarantined',linked.quarantined);
  IF action='link_account' THEN
   IF linked.user_id IS NOT NULL THEN RAISE EXCEPTION 'ACCOUNT_ALREADY_LINKED' USING ERRCODE='23505'; END IF;
   IF EXISTS(SELECT 1 FROM private.employee_account_links WHERE employee_id=target) THEN RAISE EXCEPTION 'EMPLOYEE_ALREADY_LINKED' USING ERRCODE='23505'; END IF;
  ELSE
   IF linked.employee_id IS DISTINCT FROM target THEN RAISE EXCEPTION 'ACCOUNT_LINK_MISMATCH' USING ERRCODE='55000'; END IF;
   IF linked.quarantined THEN RAISE EXCEPTION 'ACCOUNT_LINK_QUARANTINED' USING ERRCODE='55000'; END IF;
   before_data:=jsonb_build_object('account',jsonb_build_object('userId',selected_id));
  END IF;
  after_data:=jsonb_build_object('account',jsonb_build_object('userId',selected_id));
 END IF;
 context:=private.employee_context_impl_v1();
 fingerprint:=private.employee_hash(jsonb_build_object('request',p_request,'before',before_data,'after',after_data,
  'scopeVersion',context->>'scopeVersion','settingsVersion',config.version,'timezone',config.timezone,
  'selectedAccount',selected,'reportingRevision',coalesce(employee.reporting_revision,0))
  || CASE WHEN action='save_reporting' THEN jsonb_build_object('reportingGraphRevision',reporting->'graphRevision','reportingToday',reporting->'today') ELSE '{}'::jsonb END);
 RETURN jsonb_build_object('employeeId',target,'expectedVersion',expected,'action',action,'normalizedPayload',payload,
  'before',before_data,'after',after_data,'scopeVersion',context->>'scopeVersion','timezone',config.timezone,'previewFingerprint',fingerprint);
END;
$$;
CREATE FUNCTION private.employee_preview_impl_v1(p_employee_id uuid,p_expected_version bigint,p_action text,p_payload jsonb,
 p_reason text,p_effective_date date,p_source_reference text) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$
BEGIN
 PERFORM private.employee_lock_actor();
 IF p_action='save_reporting' THEN
  -- Keep the reporting preview's graph, configuration and target mutually coherent.
  PERFORM 1 FROM private.employee_settings WHERE singleton FOR SHARE;
  PERFORM 1 FROM private.employee_reporting_guard WHERE singleton FOR SHARE;
  PERFORM 1 FROM private.employee_records WHERE id=p_employee_id FOR SHARE;
 END IF;
 RETURN private.employee_prepare(private.employee_request(p_employee_id,p_expected_version,p_action,p_payload,p_reason,p_effective_date,p_source_reference));
END;
$$;
CREATE FUNCTION private.employee_command_impl_v1(p_operation_id uuid,p_employee_id uuid,p_expected_version bigint,p_action text,p_payload jsonb,
 p_reason text,p_effective_date date,p_source_reference text,p_preview_fingerprint text) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$
DECLARE actor uuid; request jsonb; fingerprint text; op private.employee_operations%ROWTYPE; preview jsonb; payload jsonb;
 selected_id uuid; claim_owner uuid; audit_id uuid:=gen_random_uuid(); version bigint; result jsonb;
BEGIN
 actor:=private.employee_lock_actor();
 request:=private.employee_request(p_employee_id,p_expected_version,p_action,p_payload,p_reason,p_effective_date,p_source_reference);
 IF p_operation_id IS NULL OR p_preview_fingerprint IS NULL OR p_preview_fingerprint!~'^[0-9a-f]{64}$' THEN RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='22023'; END IF;
 fingerprint:=private.employee_hash(request||jsonb_build_object('previewFingerprint',p_preview_fingerprint));
 PERFORM private.employee_lock_operation(actor,p_operation_id);
 SELECT * INTO op FROM private.employee_operations WHERE actor_id=actor AND operation_id=p_operation_id;
 IF op.state='abandoned' THEN RAISE EXCEPTION 'OPERATION_ABANDONED' USING ERRCODE='55000'; END IF;
 IF op.state='completed' THEN
  IF op.request_fingerprint<>fingerprint THEN RAISE EXCEPTION 'OPERATION_REUSED' USING ERRCODE='22023'; END IF;
  RETURN op.result;
 END IF;
 PERFORM 1 FROM private.employee_settings WHERE singleton FOR SHARE;
 IF p_action='save_reporting' THEN PERFORM 1 FROM private.employee_reporting_guard WHERE singleton FOR UPDATE; END IF;
 PERFORM 1 FROM private.employee_records WHERE id=p_employee_id FOR UPDATE;
 payload:=request->'payload';
 IF p_action IN('link_account','quarantine_account_link') THEN
  selected_id:=(payload->>'userId')::uuid;
  IF selected_id<>actor THEN PERFORM 1 FROM public.users WHERE id=selected_id FOR SHARE; END IF;
 END IF;
 preview:=private.employee_prepare(request);
 IF preview->>'previewFingerprint'<>p_preview_fingerprint THEN RAISE EXCEPTION 'PREVIEW_CHANGED' USING ERRCODE='40001'; END IF;
 -- Contain expected unique races; never expose constraint names or raw row details.
 BEGIN
  IF p_action='create_employee' THEN
   INSERT INTO private.employee_records(id,name,employee_number,job_title,team,recorded_status)
    VALUES(p_employee_id,payload->>'name',payload->>'employeeNumber',payload->>'jobTitle',payload->>'team',payload->>'recordedStatus');
   version:=1;
  ELSE
   UPDATE private.employee_records SET version=employee_records.version+1,updated_at=clock_timestamp() WHERE id=p_employee_id RETURNING employee_records.version INTO version;
  END IF;
  IF p_action IN('create_employee','edit_employee') THEN
   IF payload->>'employeeNumber' IS NOT NULL THEN
    INSERT INTO private.employee_number_claims(normalized_number,employee_id) VALUES(lower(payload->>'employeeNumber'),p_employee_id)
     ON CONFLICT(normalized_number) DO NOTHING;
    SELECT employee_id INTO claim_owner FROM private.employee_number_claims WHERE normalized_number=lower(payload->>'employeeNumber');
    IF claim_owner<>p_employee_id THEN RAISE EXCEPTION 'NUMBER_CLAIMED' USING ERRCODE='23505'; END IF;
   END IF;
   IF p_action='edit_employee' THEN
    UPDATE private.employee_records SET name=payload->>'name',employee_number=payload->>'employeeNumber',job_title=payload->>'jobTitle',
     team=payload->>'team',recorded_status=payload->>'recordedStatus' WHERE id=p_employee_id;
   END IF;
  ELSIF p_action='save_initial_episode' THEN
   INSERT INTO private.employee_episodes(employee_id,start_date,end_date,source_reference)
    VALUES(p_employee_id,(payload->>'startDate')::date,(payload->>'endDate')::date,payload->>'sourceReference')
    ON CONFLICT(employee_id) DO UPDATE SET start_date=EXCLUDED.start_date,end_date=EXCLUDED.end_date,source_reference=EXCLUDED.source_reference;
  ELSIF p_action='save_reporting' THEN
   PERFORM private.employee_reporting_apply(p_employee_id,payload,actor,request->>'sourceReference');
  ELSIF p_action='link_account' THEN
   INSERT INTO private.employee_account_links(user_id,employee_id) VALUES(selected_id,p_employee_id);
  ELSE
   UPDATE private.employee_account_links SET quarantined=true,quarantined_at=clock_timestamp() WHERE user_id=selected_id AND employee_id=p_employee_id;
  END IF;
 EXCEPTION WHEN unique_violation THEN
  IF p_action='save_reporting' THEN RAISE; END IF;
  IF p_action='create_employee' AND EXISTS(SELECT 1 FROM private.employee_records WHERE id=p_employee_id) THEN RAISE EXCEPTION 'EMPLOYEE_EXISTS' USING ERRCODE='23505'; END IF;
  IF p_action IN('create_employee','edit_employee') THEN RAISE EXCEPTION 'NUMBER_CLAIMED' USING ERRCODE='23505'; END IF;
  IF EXISTS(SELECT 1 FROM private.employee_account_links WHERE user_id=selected_id) THEN RAISE EXCEPTION 'ACCOUNT_ALREADY_LINKED' USING ERRCODE='23505'; END IF;
  RAISE EXCEPTION 'EMPLOYEE_ALREADY_LINKED' USING ERRCODE='23505';
 END;
 INSERT INTO private.employee_audit_events(id,employee_id,actor_id,actor_name,effective_date,action,reason,source_reference,before_data,after_data)
  VALUES(audit_id,p_employee_id,actor,(SELECT full_name FROM public.users WHERE id=actor),p_effective_date,p_action,request->>'reason',
   coalesce(request->>'sourceReference',CASE WHEN p_action='save_initial_episode' THEN payload->>'sourceReference' END),preview->'before',preview->'after');
 result:=jsonb_build_object('operationId',p_operation_id,'employeeId',p_employee_id,'version',version,'auditEventId',audit_id);
 INSERT INTO private.employee_operations(actor_id,operation_id,employee_id,action,expected_version,request_fingerprint,state,result)
  VALUES(actor,p_operation_id,p_employee_id,p_action,p_expected_version,fingerprint,'completed',result);
 RETURN result;
END;
$$;
CREATE FUNCTION private.employee_operation_impl_v1(p_operation_id uuid,p_resolution text) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$
DECLARE actor uuid; op private.employee_operations%ROWTYPE;
BEGIN
 actor:=private.employee_lock_actor();
 IF p_operation_id IS NULL OR p_resolution IS NULL OR p_resolution NOT IN('read','abandon') THEN RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='22023'; END IF;
 PERFORM private.employee_lock_operation(actor,p_operation_id);
 SELECT * INTO op FROM private.employee_operations WHERE actor_id=actor AND operation_id=p_operation_id;
 IF NOT FOUND AND p_resolution='abandon' THEN
  INSERT INTO private.employee_operations(actor_id,operation_id,state) VALUES(actor,p_operation_id,'abandoned') RETURNING * INTO op;
 END IF;
 RETURN jsonb_build_object('state',coalesce(op.state,'absent'),'result',op.result);
END;
$$;
CREATE FUNCTION public.employee_preview_v1(p_employee_id uuid,p_expected_version bigint,p_action text,p_payload jsonb,p_reason text,p_effective_date date,p_source_reference text) RETURNS jsonb
LANGUAGE sql VOLATILE SECURITY INVOKER SET search_path = pg_catalog, pg_temp AS $$ SELECT private.employee_preview_impl_v1(p_employee_id,p_expected_version,p_action,p_payload,p_reason,p_effective_date,p_source_reference); $$;
CREATE FUNCTION public.employee_command_v1(p_operation_id uuid,p_employee_id uuid,p_expected_version bigint,p_action text,p_payload jsonb,p_reason text,p_effective_date date,p_source_reference text,p_preview_fingerprint text) RETURNS jsonb
LANGUAGE sql VOLATILE SECURITY INVOKER SET search_path = pg_catalog, pg_temp AS $$ SELECT private.employee_command_impl_v1(p_operation_id,p_employee_id,p_expected_version,p_action,p_payload,p_reason,p_effective_date,p_source_reference,p_preview_fingerprint); $$;
CREATE FUNCTION public.employee_operation_v1(p_operation_id uuid,p_resolution text) RETURNS jsonb
LANGUAGE sql VOLATILE SECURITY INVOKER SET search_path = pg_catalog, pg_temp AS $$ SELECT private.employee_operation_impl_v1(p_operation_id,p_resolution); $$;
-- Revoke only the functions owned by this candidate, preserving prior read grants.
DO $$ DECLARE f record; BEGIN
 FOR f IN SELECT p.oid::regprocedure signature FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
 WHERE n.nspname IN('public','private') AND p.proname=ANY(ARRAY['employee_trim','employee_text','employee_date','employee_hash','employee_request',
 'employee_lock_actor','employee_lock_operation','employee_prepare','employee_preview_impl_v1','employee_command_impl_v1','employee_operation_impl_v1',
 'employee_preview_v1','employee_command_v1','employee_operation_v1']) LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC, anon, authenticated, service_role',f.signature);
 END LOOP;
END $$;
GRANT EXECUTE ON FUNCTION private.employee_preview_impl_v1(uuid,bigint,text,jsonb,text,date,text),
 private.employee_command_impl_v1(uuid,uuid,bigint,text,jsonb,text,date,text,text),private.employee_operation_impl_v1(uuid,text),
 public.employee_preview_v1(uuid,bigint,text,jsonb,text,date,text),public.employee_command_v1(uuid,uuid,bigint,text,jsonb,text,date,text,text),
 public.employee_operation_v1(uuid,text) TO authenticated;

-- UNPUBLISHED CANDIDATE. DO NOT RUN DIRECTLY. Transaction-neutral.
-- Loaded after schema + commands by the fixed disposable test wrappers.
-- Reporting is recorded history only, never operational access or approval routing.
SET LOCAL search_path = pg_catalog, pg_temp;

-- Pure request normalization: preserve explicit null managers and unknown gaps.
-- Sorting is canonical, but equivalent adjacent segments need not be coalesced.
CREATE FUNCTION private.employee_reporting_request(p_employee_id uuid,p_payload jsonb) RETURNS jsonb
LANGUAGE plpgsql IMMUTABLE SET search_path = pg_catalog, pg_temp AS $$
DECLARE item jsonb; manager uuid; raw text; from_day date; until_day date; intervals jsonb:='[]';
BEGIN
 IF jsonb_typeof(p_payload->'mode') IS DISTINCT FROM 'string' OR p_payload->>'mode' NOT IN('schedule','correction')
  OR jsonb_typeof(p_payload->'intervals') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='22023'; END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(p_payload->'intervals') LOOP
  IF jsonb_typeof(item) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='22023'; END IF;
  IF NOT item?&ARRAY['managerEmployeeId','from','until'] OR EXISTS(SELECT 1 FROM jsonb_object_keys(item) k WHERE k NOT IN('managerEmployeeId','from','until'))
   OR jsonb_typeof(item->'managerEmployeeId') NOT IN('string','null') THEN RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='22023'; END IF;
  raw:=item->>'managerEmployeeId'; manager:=NULL;
  IF raw IS NOT NULL THEN
   IF raw!~*'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='22023'; END IF;
   manager:=raw::uuid;
  END IF;
  IF manager=p_employee_id THEN RAISE EXCEPTION 'REPORTING_SELF_REFERENCE' USING ERRCODE='22023'; END IF;
  from_day:=private.employee_date(item->'from'); until_day:=private.employee_date(item->'until');
  IF from_day IS NULL OR until_day<=from_day THEN RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='22023'; END IF;
  intervals:=intervals||jsonb_build_array(jsonb_build_object('managerEmployeeId',manager,'from',to_char(from_day,'YYYY-MM-DD'),'until',to_char(until_day,'YYYY-MM-DD')));
 END LOOP;
 -- Compare each start with the maximum previous end, including an unbounded end.
 IF EXISTS(SELECT 1 FROM (SELECT (value->>'from')::date start_day,
    max(coalesce((value->>'until')::date,'infinity'::date)) OVER(ORDER BY (value->>'from')::date,(value->>'until')::date ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING) prior_end
   FROM jsonb_array_elements(intervals)) ordered WHERE start_day<prior_end) THEN
  RAISE EXCEPTION 'REPORTING_OVERLAP' USING ERRCODE='22023';
 END IF;
 SELECT coalesce(jsonb_agg(value ORDER BY value->>'from'),'[]') INTO intervals FROM jsonb_array_elements(intervals);
 RETURN jsonb_build_object('mode',p_payload->>'mode','intervals',intervals);
END;
$$;

-- Called by the SAME state validator for preview and commit. A reporting preview
-- holds the guard FOR SHARE; commit holds it FOR UPDATE until the outer transaction
-- ends. Re-read latest state after lock waits, never trust a pre-lock graph snapshot.
CREATE FUNCTION private.employee_reporting_prepare(p_request jsonb) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SET search_path = pg_catalog, pg_temp AS $$
DECLARE target uuid:=(p_request->>'employeeId')::uuid; payload jsonb:=p_request->'payload';
 old_intervals jsonb; proposed jsonb:=payload->'intervals'; zone text; today date; graph_revision bigint; current_revision bigint;
BEGIN
 SELECT timezone INTO zone FROM private.employee_settings WHERE singleton;
 IF zone IS NULL THEN RAISE EXCEPTION 'WORKPLACE_TIMEZONE_UNCONFIRMED' USING ERRCODE='55000'; END IF;
 -- Wall-clock civil date is evaluated after waits, including a midnight boundary.
 today:=(clock_timestamp() AT TIME ZONE zone)::date;
 SELECT employee.reporting_revision INTO current_revision FROM private.employee_records employee WHERE id=target;
 SELECT guard.revision INTO graph_revision FROM private.employee_reporting_guard guard WHERE singleton;
 IF graph_revision IS NULL THEN RAISE EXCEPTION 'REPORTING_GRAPH_UNAVAILABLE' USING ERRCODE='55000'; END IF;
 IF current_revision=9007199254740991 OR graph_revision=9007199254740991 THEN RAISE EXCEPTION 'VERSION_CONFLICT' USING ERRCODE='40001'; END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('managerEmployeeId',manager_employee_id,'from',to_char(from_date,'YYYY-MM-DD'),'until',to_char(until_date,'YYYY-MM-DD')) ORDER BY from_date,ordinal),'[]')
  INTO old_intervals FROM private.employee_reporting_intervals WHERE employee_id=target AND employee_reporting_intervals.revision=current_revision;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(proposed) i WHERE i->>'managerEmployeeId' IS NOT NULL
  AND NOT EXISTS(SELECT 1 FROM private.employee_records e WHERE e.id=(i->>'managerEmployeeId')::uuid)) THEN
  RAISE EXCEPTION 'MANAGER_NOT_FOUND' USING ERRCODE='P0002';
 END IF;
 IF payload->>'mode'='schedule' AND EXISTS(
  -- On each half-open segment of the combined change boundaries, both timelines
  -- are constant. Comparing the boundary point proves the entire past projection.
  -- A matched object with a null manager is DISTINCT from an unmatched (unknown) gap.
  WITH old_rows AS(SELECT value i FROM jsonb_array_elements(old_intervals)),
   new_rows AS(SELECT value i FROM jsonb_array_elements(proposed)),
   boundaries AS(SELECT (i->>'from')::date d FROM old_rows UNION SELECT (i->>'until')::date FROM old_rows
    UNION SELECT (i->>'from')::date FROM new_rows UNION SELECT (i->>'until')::date FROM new_rows)
  SELECT 1 FROM boundaries b
   LEFT JOIN LATERAL(SELECT jsonb_build_object('manager',i->'managerEmployeeId') state FROM old_rows WHERE (i->>'from')::date<=b.d AND (i->>'until' IS NULL OR b.d<(i->>'until')::date)) old_state ON true
   LEFT JOIN LATERAL(SELECT jsonb_build_object('manager',i->'managerEmployeeId') state FROM new_rows WHERE (i->>'from')::date<=b.d AND (i->>'until' IS NULL OR b.d<(i->>'until')::date)) new_state ON true
  WHERE b.d<today AND old_state.state IS DISTINCT FROM new_state.state
 ) THEN RAISE EXCEPTION 'REPORTING_HISTORY_CHANGE' USING ERRCODE='55000'; END IF;
 IF EXISTS(
  WITH RECURSIVE edges AS MATERIALIZED(
   SELECT i.employee_id,i.manager_employee_id,daterange(i.from_date,i.until_date,'[)') span
   FROM private.employee_reporting_intervals i JOIN private.employee_records e ON e.id=i.employee_id AND e.reporting_revision=i.revision
   WHERE i.employee_id<>target AND i.manager_employee_id IS NOT NULL
  ), walk(node,span,visited) AS(
   SELECT (i->>'managerEmployeeId')::uuid,daterange((i->>'from')::date,(i->>'until')::date,'[)'),ARRAY[target,(i->>'managerEmployeeId')::uuid]
    FROM jsonb_array_elements(proposed) i WHERE i->>'managerEmployeeId' IS NOT NULL
   UNION ALL
   SELECT e.manager_employee_id,w.span * e.span,w.visited||e.manager_employee_id
    FROM walk w JOIN edges e ON e.employee_id=w.node
    WHERE w.node<>target AND w.span && e.span AND (e.manager_employee_id=target OR NOT e.manager_employee_id=ANY(w.visited))
  ) SELECT 1 FROM walk WHERE node=target
 ) THEN RAISE EXCEPTION 'REPORTING_CYCLE' USING ERRCODE='22023'; END IF;
 RETURN jsonb_build_object('before',jsonb_build_object('reporting',old_intervals),'after',jsonb_build_object('reporting',proposed),
  'graphRevision',graph_revision,'today',to_char(today,'YYYY-MM-DD'));
END;
$$;

-- Only the common audited command dispatcher invokes this write helper after
-- locked validation. Append a full immutable revision; never rewrite prior rows.
CREATE FUNCTION private.employee_reporting_apply(p_employee_id uuid,p_payload jsonb,p_actor uuid,p_source text) RETURNS void
LANGUAGE plpgsql VOLATILE SET search_path = pg_catalog, pg_temp AS $$
DECLARE new_revision bigint;
BEGIN
 UPDATE private.employee_records SET reporting_revision=reporting_revision+1 WHERE id=p_employee_id RETURNING reporting_revision INTO new_revision;
 INSERT INTO private.employee_reporting_revisions(employee_id,revision,mode,actor_id,source_reference)
  VALUES(p_employee_id,new_revision,p_payload->>'mode',p_actor,p_source);
 INSERT INTO private.employee_reporting_intervals(employee_id,revision,ordinal,manager_employee_id,from_date,until_date)
  SELECT p_employee_id,new_revision,(ordinality-1)::integer,(value->>'managerEmployeeId')::uuid,(value->>'from')::date,(value->>'until')::date
   FROM jsonb_array_elements(p_payload->'intervals') WITH ORDINALITY;
 UPDATE private.employee_reporting_guard SET revision=revision+1 WHERE singleton;
END;
$$;
REVOKE ALL ON FUNCTION private.employee_reporting_request(uuid,jsonb),private.employee_reporting_prepare(jsonb),
 private.employee_reporting_apply(uuid,jsonb,uuid,text) FROM PUBLIC,anon,authenticated,service_role;
SELECT pg_temp.employee_assert_known('active');
DO $fresh$ DECLARE t text; n bigint; BEGIN
 IF (SELECT count(*)<>1 OR NOT bool_and(singleton AND timezone IS NULL AND version=1) FROM private.employee_settings) OR (SELECT count(*)<>1 OR NOT bool_and(singleton AND revision=0) FROM private.employee_reporting_guard) THEN RAISE EXCEPTION 'EMPLOYEE_INITIAL_SINGLETON_MISMATCH'; END IF;
 FOREACH t IN ARRAY pg_temp.employee_tables() LOOP IF t NOT IN('private.employee_settings','private.employee_reporting_guard') THEN EXECUTE format('SELECT count(*) FROM %s',t) INTO n; IF n<>0 THEN RAISE EXCEPTION 'EMPLOYEE_UNEXPECTED_INITIAL_DATA'; END IF; END IF; END LOOP;
END $fresh$;
DO $legacy$ BEGIN IF (SELECT value IS DISTINCT FROM pg_temp.employee_catalog(false) FROM employee_activation_legacy) THEN RAISE EXCEPTION 'EMPLOYEE_LEGACY_CATALOG_CHANGED'; END IF; END $legacy$;
DO $$ BEGIN RAISE EXCEPTION 'EMPLOYEE_FIXED_PRECOMMIT_FAILURE'; END $$;
COMMIT;
